    _get_ptx_module().function("convt2d")

def _pair(v):
    if isinstance(v, (tuple, list)):
        return (int(v[0]), int(v[1]))
    return (int(v), int(v))

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple, stride: tuple = (1, 1), padding: tuple = (0, 0), dilation: tuple = (1, 1), groups: int = 1, bias: bool = False):
        super().__init__()
        self.conv_transpose2d = nn.ConvTranspose2d(in_channels, out_channels, kernel_size, stride=stride, padding=padding, dilation=dilation, groups=groups, bias=bias)
        self.kernel_size = _pair(kernel_size)
        self.stride = _pair(stride)
        self.padding = _pair(padding)
        self.dilation = _pair(dilation)
        self.groups = int(groups)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        weight = self.conv_transpose2d.weight
        bias_t = self.conv_transpose2d.bias
        B, CI, H, W = x.shape
        CO = self.conv_transpose2d.out_channels
        KH, KW = self.kernel_size
        SH, SW = self.stride
        PH, PW = self.padding
        DH, DW = self.dilation
        HO = (H - 1) * SH - 2 * PH + DH * (KH - 1) + 1
        WO = (W - 1) * SW - 2 * PW + DW * (KW - 1) + 1
        out = torch.empty((B, CO, HO, WO), dtype=x.dtype, device=x.device)
        N = out.numel()
        if N == 0:
            return out
        groups = self.groups
        COG = CO // groups
        CIG = CI // groups
        if bias_t is not None:
            bias_arg = bias_t
            has_bias = 1
        else:
            bias_arg = weight
            has_bias = 0
        tile_h = (15 + (KH - 1) * DH) // SH + 2
        tile_w = (31 + (KW - 1) * DW) // SW + 2
        smem_bytes = (CIG * tile_h * tile_w + CIG * KH * KW) * 4
        module = _get_ptx_module()
        threads = 256
        module.launch(
            "convt2d",
            grid=((WO + 31) // 32, (HO + 15) // 16, B * CO),
            block=(threads, 1, 1),
            arguments=[
                x, weight, out, bias_arg,
                i32(CO), i32(HO), i32(WO), i32(CI), i32(H), i32(W),
                i32(KH), i32(KW), i32(SH), i32(SW), i32(PH), i32(PW),
                i32(DH), i32(DW), i32(COG), i32(CIG), i32(has_bias),
            ],
            shared_memory=smem_bytes,
            stream=torch.cuda.current_stream(x.device),
        )
        return out

